186	// newFlagSet 构造子命令自己的标志集。台账文件与 --json 已在打开台账前
187	// 从整条命令行统一解析，这里只保留 --json 的登记，绝不在此处重新登记
188	// -f/--file：否则子命令后的文件参数会指向与已打开台账不同的路径。
189	func newFlagSet(name string, opts *options) *flag.FlagSet {
190		fs := flag.NewFlagSet(name, flag.ContinueOnError)
191		fs.SetOutput(io.Discard)
192		fs.BoolVar(&opts.asJSON, "json", opts.asJSON, "以 JSON 输出")
193		return fs
194	}
195	
196	func parseFloat(stderr io.Writer, raw, field string) (float64, bool) {
197		v, err := strconv.ParseFloat(strings.TrimSpace(raw), 64)
198		if err != nil || math.IsNaN(v) || math.IsInf(v, 0) {
199			fmt.Fprintf(stderr, "%s 必须是有限数字\n", field)
200			return 0, false
201		}
202		return v, true
203	}
