60	// 相同目标状态也继续报保存错误。恢复可写后无需重开，重新提交成功才生效。
61	func TestStatusSaveFailureIsFileErrorAndRecoverable(t *testing.T) {
62		dir := chdirTemp(t)
63		// 台账放在子目录里：把子目录改成只读即可挡住写临时文件与改名替换，
64		// 已存在的台账文件本身仍可读，查询不受影响。
65		sub := filepath.Join(dir, "只读目录")
