70	
71		// M-1：登记（待校准）+ 合格未到期证书，始终未切换为在用。
72		if r := runArgs(t, registerArgs(target, "M-1")...); r.code != 0 {
73			t.Fatalf("登记 M-1 失败 code=%d stderr=%s", r.code, r.stderr)
74		}
75		if r := runArgs(t, certForArgs(target, "M-1", "C-1", "2026-09-01")...); r.code != 0 {
76			t.Fatalf("M-1 录证书失败 code=%d stderr=%s", r.code, r.stderr)
77		}
78		// M-2：登记 + 合格未到期证书 + 成功切换为在用。
79		if r := runArgs(t, registerArgs(target, "M-2")...); r.code != 0 {
80			t.Fatalf("登记 M-2 失败 code=%d stderr=%s", r.code, r.stderr)
81		}
82		if r := runArgs(t, certForArgs(target, "M-2", "C-2", "2026-09-02")...); r.code != 0 {
83			t.Fatalf("M-2 录证书失败 code=%d stderr=%s", r.code, r.stderr)
84		}
85		if r := runArgs(t, statusArgs(target, "M-2", "在用", false)...); r.code != 0 {
86			t.Fatalf("M-2 切换在用应成功 code=%d stderr=%s", r.code, r.stderr)
87		}
88	
89		// 目录只读：save 无法创建临时文件；测试结束后恢复权限便于清理。
90		if err := os.Chmod(sub, 0o555); err != nil {
91			t.Fatal(err)
92		}
93		t.Cleanup(func() { _ = os.Chmod(sub, 0o755) })
94	
95		// M-1 待校准 → 在用：写盘失败，退出码 2，不输出切换成功信息。
96		r := runArgs(t, statusArgs(target, "M-1", "在用", false)...)
97		if r.code != 2 {
98			t.Fatalf("状态写盘失败应按文件读写错误退出 2，得到 %d", r.code)
99		}
100		if strings.Contains(r.stdout, "已切换为") {
101			t.Fatalf("写盘失败不得输出切换成功信息：stdout=%q", r.stdout)
102		}
103		if !strings.Contains(r.stderr, target) {
104			t.Fatalf("错误应指出台账文件 %s，stderr=%q", target, r.stderr)
105		}
106	
107		// --json 模式同样退出码 2，且不输出 accepted:true 的成功结果。
108		rj := runArgs(t, statusArgs(target, "M-1", "在用", true)...)
109		if rj.code != 2 {
110			t.Fatalf("--json 模式写盘失败也应退出 2，得到 %d", rj.code)
111		}
112		if strings.Contains(rj.stdout, `"accepted": true`) ||
113			strings.Contains(rj.stdout, "已切换为") {
114			t.Fatalf("--json 写盘失败不得输出成功结果：stdout=%q", rj.stdout)
115		}
116	
117		// 文件仍不可写时再次提交相同目标状态：仍退出 2，而不是当成“状态未变”
118		// 直接成功。
119		r2 := runArgs(t, statusArgs(target, "M-1", "在用", false)...)
120		if r2.code != 2 {
121			t.Fatalf("再次提交失败状态应仍退出 2，得到 %d", r2.code)
122		}
123	
124		// M-2 在用 → 停用同样写盘失败，不能提前按停用限制使用。
125		rr := runArgs(t, statusArgs(target, "M-2", "停用", false)...)
126		if rr.code != 2 || strings.Contains(rr.stdout, "已切换为") {
127			t.Fatalf("M-2 停用写盘失败应退出 2 且无成功输出：code=%d stdout=%q", rr.code, rr.stdout)
128		}
129		if rr2 := runArgs(t, statusArgs(target, "M-2", "停用", false)...); rr2.code != 2 {
130			t.Fatalf("再次提交停用应仍退出 2，得到 %d", rr2.code)
131		}
132	
133		// 只读目录下台账文件仍可读：核对按最后成功保存的状态判断。
134		st1, can1, reasons1 := reviewStatus(t, target, "M-1")
135		if st1 != "待校准" || can1 || !reasonContains(reasons1, "待校准") {
136			t.Fatalf("M-1 应仍为待校准且不可使用：status=%s canUse=%v reasons=%v",
137				st1, can1, reasons1)
138		}
139		st2, can2, reasons2 := reviewStatus(t, target, "M-2")
140		if st2 != "在用" || !can2 || len(reasons2) != 0 {
141			t.Fatalf("M-2 应仍为在用且可使用，不能提前受限：status=%s canUse=%v reasons=%v",
142				st2, can2, reasons2)
143		}
144	
145		// 恢复目录可写：无需删除任何残留，重新提交才真正生效。
146		if err := os.Chmod(sub, 0o755); err != nil {
147			t.Fatal(err)
148		}
149		ok := runArgs(t, statusArgs(target, "M-1", "在用", false)...)
150		if ok.code != 0 || !strings.Contains(ok.stdout, "已切换为在用") {
151			t.Fatalf("恢复后 M-1 切换在用应成功：code=%d stdout=%q stderr=%s",
152				ok.code, ok.stdout, ok.stderr)
153		}
154		off := runArgs(t, statusArgs(target, "M-2", "停用", false)...)
155		if off.code != 0 || !strings.Contains(off.stdout, "已切换为停用") {
156			t.Fatalf("恢复后 M-2 停用应成功：code=%d stdout=%q stderr=%s",
157				off.code, off.stdout, off.stderr)
158		}
159	
160		// 成功保存后核对按新状态判断。
161		st1, can1, reasons1 = reviewStatus(t, target, "M-1")
162		if st1 != "在用" || !can1 {
163			t.Fatalf("M-1 成功切换后应为在用且可使用：status=%s canUse=%v reasons=%v",
164				st1, can1, reasons1)
165		}
166		st2, can2, reasons2 = reviewStatus(t, target, "M-2")
167		if st2 != "停用" || can2 || !reasonContains(reasons2, "停用") {
168			t.Fatalf("M-2 成功停用后应不可使用且原因含停用：status=%s canUse=%v reasons=%v",
169				st2, can2, reasons2)
170		}
171	
172		// 请求状态等于最后成功保存的状态时直接成功，不要求再次写盘：目录重新
173		// 只读也应返回成功。
174		if err := os.Chmod(sub, 0o555); err != nil {
175			t.Fatal(err)
176		}
177		same := runArgs(t, statusArgs(target, "M-1", "在用", true)...)
178		if same.code != 0 || !strings.Contains(same.stdout, `"accepted": true`) {
179			t.Fatalf("重复提交当前状态应直接成功且不写盘：code=%d stdout=%q stderr=%s",
180				same.code, same.stdout, same.stderr)
181		}
182		if err := os.Chmod(sub, 0o755); err != nil {
183			t.Fatal(err)
184		}
185	
186		// 重新打开台账文件（新进程方式）能读到成功切换的状态。
187		st1, can1, _ = reviewStatus(t, target, "M-1")
188		st2, _, _ = reviewStatus(t, target, "M-2")
189		if st1 != "在用" || st2 != "停用" {
190			t.Fatalf("重开核对状态异常：M-1=%s M-2=%s", st1, st2)
191		}
192	}
